+// Número de factura: SUC(3)-GESTION(4)-CORRELATIVO(6), con ceros a la izquierda.
+// SUPUESTO pendiente de confirmar contra el estándar de la empresa (no estaba en el repo ni en el brain).
+export function numeroFactura(sucursal, gestion, correlativo) {
+  const parte = (valor, nombre, digitos) => {
+    if (!Number.isInteger(valor) || valor < 1 || valor >= 10 ** digitos)
+      throw new RangeError(`${nombre} inválido: entero de 1 a ${"9".repeat(digitos)}`);
+    return String(valor).padStart(digitos, "0");
+  };
+  if (!Number.isInteger(gestion) || gestion < 1000 || gestion > 9999) throw new RangeError("gestion inválida: año de 4 dígitos");
+  return `${parte(sucursal, "sucursal", 3)}-${gestion}-${parte(correlativo, "correlativo", 6)}`;
+}
